#!/usr/bin/env python3
"""Read-only Git-index audit of generated files and competing root documents.

Local virtual environments, shader caches, and distribution outputs are
allowed in a developer's working directory, but never in the Git index.
Stable Godot .gd.uid source references are intentional and must be preserved.
"""
from __future__ import annotations

import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
GENERATED_DIRS = frozenset({
    ".godot", ".venv", ".pytest_cache", "__pycache__",
    ".rubricnet-venv", "node_modules", ".mypy_cache", ".ruff_cache",
    "dist", "build",
})
GENERATED_SUFFIXES = (".pyc", ".pyo", ".pyd", ".swp")
OLD_ROOT_PLANS = frozenset({"NOTATION_RENDERING.md"})


def audit_paths(paths: list[str]) -> list[str]:
    issues = []
    for path in paths:
        parts = Path(path).parts
        if any(part in GENERATED_DIRS for part in parts):
            issues.append(f"Generated directory tracked: {path}")
        elif path.endswith(GENERATED_SUFFIXES):
            issues.append(f"Generated bytecode/editor file tracked: {path}")
        elif path in OLD_ROOT_PLANS:
            issues.append(f"Superseded root plan tracked: {path}")
    return issues



def audit_workflow_triggers(root: Path = ROOT) -> list[str]:
    """Check literal path filters against live files, separately per event."""
    import re

    issues = []
    for workflow in sorted((root / ".github" / "workflows").glob("*.yml")):
        event = ""
        in_paths = False
        seen = set()
        for line in workflow.read_text(encoding="utf-8").splitlines():
            section = re.match(r"^  (push|pull_request|workflow_call|workflow_dispatch|workflow_run):\s*$", line)
            if section:
                event = section.group(1)
                in_paths = False
            if line == "    paths:" and event in ("push", "pull_request"):
                in_paths = True
                seen = set()
                continue
            if not in_paths:
                continue
            entry = re.match(r"^      - ['\"]?([^'\"]+?)['\"]?\s*$", line)
            if entry:
                target = entry.group(1)
                if target in seen:
                    issues.append(f"{workflow.name}: duplicate {event} path {target}")
                seen.add(target)
                if not any(char in target for char in "*?[]{}!") and not (root / target).is_file():
                    issues.append(f"{workflow.name}: missing {event} trigger {target}")
            elif line.strip() and not line.startswith("      "):
                in_paths = False
    return issues


def audit_core_document_links(root: Path = ROOT) -> list[str]:
    """Only live entry points and technical contracts; archives are historical."""
    import re
    from urllib.parse import unquote

    issues = []
    canonical = (
        "README.md", "ROADMAP.md", "docs/README.md",
        "docs/architecture/system.md",
        "docs/architecture/composed-midi-generators.md",
        "docs/inprocess-runtime.md",
        "docs/archive/development/README.md",
        "scripts/research/README.md",
    )
    for relative in canonical:
        page = root / relative
        if not page.is_file():
            issues.append(f"Missing canonical document: {relative}")
            continue
        text = page.read_text(encoding="utf-8")
        for match in re.finditer(r"(?<!!)\[[^\]]+\]\(([^)]+)\)", text):
            target = match.group(1).split()[0].split("#")[0].strip("<>")
            if not target or "://" in target or target.startswith(("mailto:", "data:")):
                continue
            absolute = (page.parent / unquote(target)).resolve()
            if not absolute.is_file():
                issues.append(f"{relative}: unresolved local link {target}")
    return issues


def audit_repo(root: Path = ROOT) -> list[str]:
    completed = subprocess.run(
        ["git", "-C", str(root), "ls-files", "-z"],
        capture_output=True, check=False,
    )
    if completed.returncode:
        return [f"Cannot read Git index: {completed.stderr.decode(errors='replace').strip()}"]
    paths = [part.decode("utf-8", errors="replace")
             for part in completed.stdout.split(b"\0") if part]
    issues = audit_paths(paths)
    issues.extend(audit_workflow_triggers(root))
    issues.extend(audit_core_document_links(root))
    for name in ("README.md", "ROADMAP.md", "docs/README.md"):
        if name not in paths:
            issues.append(f"Missing canonical documentation entry: {name}")
    if (root / "ROADMAP.md").is_file() and "sole active phase plan" not in (
            root / "ROADMAP.md").read_text(encoding="utf-8"):
        issues.append("ROADMAP.md must identify the sole active phase plan")
    return issues


def main() -> int:
    issues = audit_repo()
    if issues:
        print("\n".join(issues))
        return 1
    print("REPOSITORY_HYGIENE_OK")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
